#include <map>
#include <string>

int ReadDetached(std::map<std::string, int>& counts) {
  auto detached = counts.extract("draft");
  if (detached.empty()) return -1;
  return detached.mapped();
  // При выходе невставленный узел уничтожается вместе с detached.
}

#include <functional>
#include <map>
#include <string>
#include <string_view>

bool HasUser(const std::map<std::string, int, std::less<>>& users,
             std::string_view query) {
  return users.contains(query);
}

#include <map>

bool Present(const std::map<int, int>& values, int key) {
  return values.find(key) != values.end();
}
// В этом примере тип запроса и тип хранимого ключа совпадают.
